package operators;

public class LogicalOperator {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n1=30,n2=40;
		boolean A=n1==n2;
		boolean B=n1<=n2;
		 System.out.println("logial and:A&&B"+(A&&B));
		 System.out.println("logial not:!A"+(!A));
		 System.out.println("logial or:A||B"+(A|B));

		 
		

	}

}
